{
  "name": "mistral-vibe-desktop",
  "version": "0.1.0",
  "description": "Minimal Windows desktop wrapper for Mistral Vibe",
  "main": "main.js",
  "author": "Josh",
  "license": "MIT",
  "scripts": {
    "start": "electron .",
    "dist": "electron-builder --win"
  },
  "devDependencies": {
    "electron": "latest",
    "electron-builder": "latest"
  },
  "build": {
    "appId": "com.josh.mistralvibedesktop",
    "productName": "Mistral Vibe Desktop",
    "directories": {
      "output": "dist"
    },
    "files": [
      "main.js",
      "package.json",
      "build/icon.svg"
    ],
    "win": {
      "target": "nsis",
      "icon": "build/icon.svg"
    },
    "nsis": {
      "oneClick": false,
      "allowToChangeInstallationDirectory": true,
      "createDesktopShortcut": true,
      "createStartMenuShortcut": true
    }
  }
}

const { app, BrowserWindow, shell } = require("electron");

let mainWindow = null;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1280,
    height: 850,
    minWidth: 800,
    minHeight: 600,
    title: "Mistral Vibe",
    autoHideMenuBar: true,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      sandbox: true
    }
  });

  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    try {
      const parsed = new URL(url);

      const allowedHosts = [
        "chat.mistral.ai",
        "auth.mistral.ai",
        "mistral.ai"
      ];

      if (
        allowedHosts.includes(parsed.hostname) ||
        parsed.hostname.endsWith(".mistral.ai")
      ) {
        return {
          action: "allow",
          overrideBrowserWindowOptions: {
            width: 520,
            height: 720,
            autoHideMenuBar: true,
            webPreferences: {
              nodeIntegration: false,
              contextIsolation: true,
              sandbox: true
            }
          }
        };
      }

      shell.openExternal(url);
      return { action: "deny" };
    } catch {
      return { action: "deny" };
    }
  });

  mainWindow.loadURL("https://chat.mistral.ai/");

  mainWindow.on("closed", () => {
    mainWindow = null;
  });
}

app.whenReady().then(() => {
  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});
